//! Support for the code generated by the macros of this crate. Not part of the public API.

use crate::recorder::Recorder;
use crate::value::{Encoder, Record, ValueWriter};
use std::any::Any;
use std::panic::Location;

/// Records any value, with its implementation of `Record` if it has one, or by its type otherwise.
///
/// The choice is made with autoref-based specialization: `(&Probe(&x)).__pmdb_record(w)` resolves
/// to `ViaRecord` if the type of `x` implements `Record`, or to `ViaName` otherwise. The choice is
/// made where the call is written, so values of generic types are recorded according to the bounds
/// of their type parameters.
pub mod probe {
  use super::*;

  pub struct Probe<'a, T: ?Sized>(pub &'a T);

  // The traits' methods take `self` by value, which requires a copy when the receiver is
  // dereferenced to find the implementing type.
  impl<T: ?Sized> Clone for Probe<'_, T> {
    fn clone(&self) -> Self {
      *self
    }
  }

  impl<T: ?Sized> Copy for Probe<'_, T> {}

  pub trait ViaRecord {
    fn __pmdb_record(self, w: ValueWriter<'_>);
  }

  impl<T: Record + ?Sized> ViaRecord for &Probe<'_, T> {
    fn __pmdb_record(self, w: ValueWriter<'_>) {
      self.0.record(w)
    }
  }

  pub trait ViaName {
    fn __pmdb_record(self, w: ValueWriter<'_>);
  }

  impl<T: ?Sized> ViaName for Probe<'_, T> {
    fn __pmdb_record(self, w: ValueWriter<'_>) {
      let name = std::any::type_name::<T>();
      if name.ends_with("{{closure}}") {
        // Record closures as functions named after the function defining them, like Python's
        // `<lambda>`s are recorded with the qualified name of their enclosing function.
        w.function(&simplified(name, ""))
      } else {
        w.string(&format!("<{name} object>"))
      }
    }
  }
}

/// Returns the encoding of the value written by `write`.
pub fn encode(write: impl FnOnce(ValueWriter<'_>)) -> Vec<u8> {
  Encoder::encode(write)
}

/// Records the value encoded as `value` with the given `label` in `recorder`, where this function
/// is called in the crate whose manifest is in the directory `manifest`.
#[track_caller]
pub fn snap(recorder: &Recorder, manifest: &'static str, label: &str, value: Vec<u8>) {
  let l = Location::caller();
  recorder.snapshot_encoded(
    resolve(l.file(), Some(manifest)),
    l.line(),
    Some(label),
    value,
  )
}

/// Returns the name under which to record the function whose body contains `marker`, which is
/// the type name of a function item declared in that body, in the module at path `module`.
///
/// Type names of nested items have the form `module::Type<Args>::method::marker` or
/// `<module::Type<Args> as module::Trait>::method::marker`. The result drops the marker, the
/// trait, the path of the module, generic arguments, and closures, giving `Type::method`.
pub fn qualified_name(marker: &str, module: &str) -> String {
  simplified(
    marker
      .rsplit_once("::")
      .map_or(marker, |(prefix, _)| prefix),
    module,
  )
}

/// Returns the path `name` without traits, the path of `module`, generic arguments, and closures.
fn simplified(name: &str, module: &str) -> String {
  // Items nested in recorded functions are in the closure wrapping their body.
  let name = name.replace("::{{closure}}", "");
  let name = &name[..];

  // Drop the trait of `<Type as Trait>::method`.
  let name = match name.strip_prefix('<') {
    Some(rest) => {
      let end = closing_bracket(rest);
      let receiver = &rest[..end];
      let receiver = receiver.rsplit_once(" as ").map_or(receiver, |(r, _)| r);
      format!("{receiver}{}", &rest[(end + 1).min(rest.len())..])
    }
    None => name.to_string(),
  };

  // Drop generic arguments.
  let mut result = String::with_capacity(name.len());
  let mut rest = &name[..];
  while let Some(i) = rest.find('<') {
    result.push_str(&rest[..i]);
    let after = &rest[i + 1..];
    rest = &after[(closing_bracket(after) + 1).min(after.len())..];
  }
  result.push_str(rest);

  match result
    .strip_prefix(module)
    .and_then(|n| n.strip_prefix("::"))
  {
    Some(n) => n.to_string(),
    None => result,
  }
}

/// Returns the position of the angle bracket closing the one preceding `s`.
fn closing_bracket(s: &str) -> usize {
  let mut depth = 1;
  for (i, c) in s.char_indices() {
    match c {
      '<' => depth += 1,
      // Skip the arrows of function types (e.g., `dyn Fn() -> T`).
      '>' if i > 0 && s.as_bytes()[i - 1] == b'-' => {}
      '>' => {
        depth -= 1;
        if depth == 0 {
          return i;
        }
      }
      _ => {}
    }
  }
  s.len()
}

/// Returns `file`, which is a path reported by `Location`, made absolute if possible.
///
/// The paths of the source files of a crate are relative to the directory in which `rustc` was
/// invoked, which is either the directory of the crate's manifest, given by `manifest`, or the
/// root of its workspace. `pmdb` needs absolute paths to show the sources of a trace when it
/// doesn't run in that directory, so relative paths are resolved against the ancestors of
/// `manifest`, or of the current directory if `manifest` is `None`.
pub(crate) fn resolve(file: &'static str, manifest: Option<&'static str>) -> &'static str {
  use std::collections::HashMap;
  use std::path::{Path, PathBuf};
  use std::sync::{LazyLock, Mutex};

  if Path::new(file).is_absolute() {
    return file;
  }

  type Cache = HashMap<(&'static str, Option<&'static str>), &'static str>;
  static CACHE: LazyLock<Mutex<Cache>> = LazyLock::new(Default::default);
  let mut cache = CACHE.lock().unwrap_or_else(|e| e.into_inner());
  cache.entry((file, manifest)).or_insert_with(|| {
    let base = match manifest {
      Some(m) => PathBuf::from(m),
      None => match std::env::current_dir() {
        Ok(d) => d,
        Err(_) => return file,
      },
    };
    base
      .ancestors()
      .map(|a| a.join(file))
      .find(|p| p.is_file())
      .and_then(|p| p.to_str().map(|s| &*Box::leak(s.into())))
      .unwrap_or(file)
  })
}

/// A recorded call whose result has yet to be recorded.
pub struct Frame<'r> {
  recorder: &'r Recorder,
  file: &'static str,
  line: u32,
  function: &'static str,
}

impl<'r> Frame<'r> {
  /// Records a call to `function` with the given encoded `arguments` at `location`, in the crate
  /// whose manifest is in the directory `manifest`.
  pub fn enter(
    recorder: &'r Recorder, location: &'static Location<'static>, manifest: &'static str,
    function: &'static str, arguments: Vec<Vec<u8>>,
  ) -> Self {
    let file = resolve(location.file(), Some(manifest));
    let line = location.line();
    recorder.step_into(file, line, function, &arguments);
    Self {
      recorder,
      file,
      line,
      function,
    }
  }

  /// Records `result` as the value returned by the call.
  pub fn result(self, result: Vec<u8>) {
    let label = format!("{}.$result", self.function);
    self.recorder.step_out(self.file, self.line, &label, result);
  }

  /// Records the panic whose payload is `payload` as the outcome of the call.
  pub fn panic(self, payload: &(dyn Any + Send)) {
    let message = payload
      .downcast_ref::<&str>()
      .copied()
      .or_else(|| payload.downcast_ref::<String>().map(String::as_str))
      .unwrap_or("<panic>");
    let exception = encode(|w| {
      let mut t = w.table(2);
      t.entry("type").string("panic");
      t.entry("message").string(message);
    });
    let label = format!("{}.$exception", self.function);
    self
      .recorder
      .step_out(self.file, self.line, &label, exception);
  }
}
